                                                continue;
                                        }
                                        submatrix[subi][subj] = matrix[i][j];
                                        subj++;
                                }
                                subi++;
                        }
                        det = det + (pow(-1, x) * matrix[0][x] * determinant(submatrix, n-1));
                }
        }
        return det;
}

