use std::collections::HashSet;

// Recursive function to generate permutations
fn recur_permute(s: &str, x: String, res: &mut HashSet<String>) {
    // If string s becomes empty, then we have a permutation stored in x
    if s.is_empty() {
        // Store the permutation in res
        res.insert(x);
        return;
    }

    // Iterate through the string
    for i in 0..s.len() {
        // Remove the first character from string s and add to string x
        let first_char = &s[i..i + 1]; // Take the character at position `i`
        let rest = format!("{}{}", &s[0..i], &s[i + 1..]); // Remove this character from `s`

        // Recursive call with updated values
        let next_x = format!("{}{}", x, first_char);
        recur_permute(&rest, next_x, res); // Pass the remaining string and the new prefix
    }
}

// Function to find all permutations of the string
fn find_permutation(s: &str) -> Vec<String> {
    // To store all unique permutations
    let mut res = HashSet::new();

    // Call the recursive function
    recur_permute(s, String::new(), &mut res);

    // Return the results as a vector
    let mut ans: Vec<String> = res.into_iter().collect();
    ans.sort(); // Sort the result to match the order of output in the C++ program
    ans
}

fn main() {
    let s = "ABC";
    let ans = find_permutation(s);

    // Print the permutations
    for i in ans {
        println!("{}", i);
    }
}
